// Williams' even-weight ring is generated by E2, phi2, phi4, phi6,
// psi6, psi3^2, phi8. Products of odd-weight generators are needed.
// Keep eval at top level for compatibility with run_tests.m.

SetMemoryLimit(16*1024^3);
SetNthreads(4);
J := LoadStoredCanonicalRing("2.2.29.1-1.1");
R := Generic(J);
assert VariableWeights(R) eq [2,2,4,6,6,6,8];

litfile := "Verification/LiteratureEquations/2.2.29.1-1.1-Williams.m";
LitData := eval (Read(litfile) cat "\nreturn LitData;");
I, PhiImages, PsiImages, citation, WilliamsIdeal, evenGenerators := LitData(R,R);
W := Generic(WilliamsIdeal);
assert VariableWeights(W) eq [2,2,3,3,4,5,6,6,7,8,9];
assert #Generators(WilliamsIdeal) eq 35;
assert IsHomogeneous(WilliamsIdeal);
assert [WeightedDegree(f) : f in evenGenerators] eq VariableWeights(R);

inclusion := hom<R -> W | evenGenerators>;
assert &and[inclusion(f) in WilliamsIdeal : f in Generators(I)];

// Every even monomial factors into even variables and pairs of odd variables.
evens := [i : i in [1..Rank(W)] | IsEven(WeightedDegree(W.i))];
odds := [i : i in [1..Rank(W)] | IsOdd(WeightedDegree(W.i))];
candidates := [W.i : i in evens] cat [W.i*W.j : i,j in odds | i le j];
for w in Sort(Setseq({WeightedDegree(f) : f in candidates})) do
    products := [NormalForm(inclusion(m),WilliamsIdeal)
                 : m in MonomialsOfWeightedDegree(R,w)];
    targets := [NormalForm(f,WilliamsIdeal) : f in candidates | WeightedDegree(f) eq w];
    terms := Setseq(&join[Set(Monomials(f)) : f in products cat targets]);
    rows := [[MonomialCoefficient(f,m) : m in terms] : f in products];
    allRows := rows cat [[MonomialCoefficient(f,m) : m in terms] : f in targets];
    assert Rank(Matrix(Rationals(),rows)) eq Rank(Matrix(Rationals(),allRows));
end for;

h := HilbertSeries(WilliamsIdeal);
t := Parent(h).1;
assert (h + Evaluate(h,-t))/2 eq HilbertSeries(I);
print "PASS Williams even presentation: generation, kernel and exact Hilbert series";

assert VerifyGradedIsomorphism(I,J,PhiImages,PsiImages);
printf "Q(sqrt29) level 1: VerifyGradedIsomorphism = true against %o.\n", citation;
